def load(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def vsha(x):return hashlib.sha256(json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def save(n,x):(O/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def ptr(x,p):
 for k in p.strip('/').split('/') if p else []:
  k=k.replace('~1','/').replace('~0','~');x=x[int(k)] if isinstance(x,list) else x[k]
 return x
BOUND={};CHECKS=[]
def ck(n,v):CHECKS.append({'check':n,'passed':bool(v)});assert v,n
def evidence(p,pointer,note):
 p=Path(p);x=load(p);v=ptr(x,pointer);BOUND[str(p)]=sha(p)
 return {'path':str(p),'sha256':sha(p),'json_pointer':pointer,'value_sha256':vsha(v),'scope':note}
def rec(n):return S/'data/records'/(n+'.json')
def byid(path,section,id):
 x=load(path);return '/'+section+'/'+str(next(i for i,z in enumerate(x[section]) if z.get('id',z.get('sample_id'))==id))
def measure(n,id):return byid(rec(n),'measurements',id)
